exports.GenerateIdPDF = async (req, res) => {
    const { 
        id
    } = req.params;
    let browser;
    try {

        const employee = await db.Employee.findByPk(id);
        const employment = await db.Employment.findOne({
            where: {
                employee_id: employee.id
            }
        });
        const position = await db.Position.findOne({
            where: {
                id: employment.position_id
            }
        });
        const p = await db.EmployeePhoto.findOne({
            where: {
                employee_id: employee.id
            }
        });
        const s = await db.EmployeeSignature.findOne({
            where: {
                employee_id: employee.id
            }
        });

        const templatePath = __nccwpck_require__.ab + "ID.pug";

        const front = 'data:image/png;base64,' + fs.readFileSync(__nccwpck_require__.ab + "Front.png").toString('base64');
        const back = 'data:image/png;base64,' + fs.readFileSync(__nccwpck_require__.ab + "Back.png").toString('base64');

        const photo = 'data:image/png;base64,' + fs.readFileSync(__nccwpck_require__.ab + "public/" + p.avatar).toString('base64');
        const signature = 'data:image/png;base64,' + fs.readFileSync(__nccwpck_require__.ab + "public/" + s.signature).toString('base64');

        const FormatEmployeeName = (employee) => {
            if (!employee) return '';

            const first = employee.first_name || '';
            const middle = employee.middle_name
                ? `${employee.middle_name.charAt(0)}.`
                : '';
            const last = employee.last_name || '';
            const suffix = employee.suffix ? ` ${employee.suffix}` : '';

            return `${first} ${middle} ${last}${suffix}`
                .replace(/\s+/g, ' ')
                .trim();
        };


        const QRCode = QR.drawImg(employment?.employee_no, {
            typeNumber: 2,
            errorCorrectLevel: 'M',
            size: 500
        });

        const html = pug.renderFile(__nccwpck_require__.ab + "ID.pug", { 
            front,
            back,
            photo,
            signature,
            name: FormatEmployeeName(employee),
            position: position.name,
            contactNo: employee.contact_number,
            address: employee.address,
            employeeNo: employment?.employee_no,
            qr: QRCode
        });
        const browser = await puppeteer.launch({
          headless: 'new',
          args: ['--no-sandbox', '--disable-setuid-sandbox']
        });
        
        const page = await browser.newPage();
    
        await page.setContent(html, { waitUntil: 'networkidle0' });

        await page.emulateMediaType('print');

        const width = '2.125in'
        const height = '3.375in'
    
        const pdfBuffer = await page.pdf({
            width: width, 
            height: height, 
            landscape: false, 
            margin: {
                top: '0px',
                bottom: '0px',
                left: '0px',
                right: '0px'
            }, 
            preferCSSPageSize: true,
            printBackground: true
        });

        const buffer = Buffer.from(pdfBuffer);
        res.send(buffer)

    } catch (error) {
        res.status(500).json({ error: error.message });
    } finally {
        if (browser) {
            await browser.close();
        }
    }
};

