const pos = (n) => (n > 0 ? n : 0);

const combineDayTime = (workDay, timeStr) => {
  const t = (timeStr || "").trim();
  if (!t) return moment.invalid();

  // Accept HH:mm or HH:mm:ss
  const m = moment(
    `${workDay} ${t}`,
    ["YYYY-MM-DD HH:mm:ss", "YYYY-MM-DD HH:mm"],
    true
  );

  // If still invalid, try padding seconds
  if (!m.isValid() && t.length === 5) {
    return moment(`${workDay} ${t}:00`, "YYYY-MM-DD HH:mm:ss", true);
  }

  return m;
};

const pickEffectiveEmployeeShift = (employeeShifts, workDayYMD) => {
  const day = moment(workDayYMD, "YYYY-MM-DD", true);

  const valid = (employeeShifts || [])
    .filter((es) => es.is_active)
    .filter((es) => {
      const from = moment(es.effective_from, "YYYY-MM-DD", true);
      const to = es.effective_to ? moment(es.effective_to, "YYYY-MM-DD", true) : null;
      return from.isSameOrBefore(day, "day") && (!to || to.isSameOrAfter(day, "day"));
    })
    .sort((a, b) => moment(b.effective_from).diff(moment(a.effective_from)));

  return valid[0] || null;
};

const overlapMinutes = (aStart, aEnd, bStart, bEnd) => {
  const start = moment.max(aStart, bStart);
  const end = moment.min(aEnd, bEnd);
  const diff = end.diff(start, "minutes");
  return diff > 0 ? diff : 0;
};

// Approved overtime schedules for employee on workDay
const getApprovedOvertimesForDay = async ({ employeeId, workDay, transaction }) => {
  return db.EmployeeOvertimeApplication.findAll({
    where: {
      employee_id: employeeId,
      status: "Approved",
    },
    include: [
      {
        model: db.Overtime,
        as: "overtime",
        required: true,
        where: {
          date: workDay,
          status: "Approved",
          is_active: true,
        },
      },
    ],
    transaction,
  });
};

exports.GetAttendance = async (req, res) => {
  const employeeId = parseInt(req.query.id, 10);

  const year = req.query.year ? String(req.query.year) : null;
  const month = req.query.month
    ? String(req.query.month).padStart(2, "0")
    : null;

  const PH_OFFSET = 8;

  const formatTime = (t) =>
    t ? moment(t, ["HH:mm:ss", "HH:mm"]).format("HH:mm") : "";

  const formatTimeHHmmA = (t) =>
    t ? moment(t, ["HH:mm:ss", "HH:mm"]).format("hh:mm A") : "";

  try {
    if (!employeeId || !year || !month) {
      return res.status(400).json({
        error:
          "Missing required params. Use req.query.id, req.query.year, req.query.month.",
      });
    }

    const monthStart = moment(`${year}-${month}-01`, "YYYY-MM-DD")
      .startOf("day");

    const monthEnd = monthStart.clone().endOf("month").endOf("day");

    const startYMD = monthStart.format("YYYY-MM-DD");
    const endYMD = monthEnd.format("YYYY-MM-DD");

    // ==========================================
    // ALWAYS FETCH LOGS FIRST (WORKS FOR BOTH CASES)
    // ==========================================
    const logRows = await db.EmployeeLog.findAll({
      where: {
        employee_id: employeeId,
        captured_at: {
          [Op.between]: [monthStart.toDate(), monthEnd.toDate()],
        },
      },
      attributes: ["captured_at"],
      order: [["captured_at", "ASC"]],
    });

    // ==========================================
    // BUILD LOG MAP (PH TIME)
    // ==========================================
    const logsMap = {};

    for (const log of logRows) {
      // Convert UTC to PH time
      const m = moment.utc(log.captured_at).utcOffset(PH_OFFSET);

      const key = m.format("YYYY-MM-DD");
      const t = m.format("HH:mm");

      if (!logsMap[key]) logsMap[key] = [];

      logsMap[key].push(t);
    }

    // Pad all days in month
    let padDay = monthStart.clone();
    while (padDay.isSameOrBefore(monthEnd, "day")) {
      const key = padDay.format("YYYY-MM-DD");

      const times = logsMap[key]
        ? [...new Set(logsMap[key])].sort()
        : [];

      const paddedTimes =
        times.length < 4
          ? [...times, ...Array(4 - times.length).fill("")]
          : times.slice(0, 4);

      logsMap[key] = paddedTimes;

      padDay.add(1, "day");
    }

    // ==========================================
    // FETCH ATTENDANCE
    // ==========================================
    const attendance = await db.Attendance.findOne({
      where: {
        employee_id: employeeId,
        date_from: { [Op.lte]: endYMD },
        date_to: { [Op.gte]: startYMD },
      },
      order: [["date_from", "DESC"]],
      include: [
        {
          model: db.EmployeeAttendance,
          as: "days",
          separate: true,
          order: [["work_day", "ASC"]],
        },
      ],
    });

    // ==========================================
    // IF NO ATTENDANCE — RETURN LOGS ONLY
    // ==========================================
    if (!attendance) {
      const results = [];

      let d = monthStart.clone();

      while (d.isSameOrBefore(monthEnd, "day")) {
        const key = d.format("YYYY-MM-DD");

        results.push({
          date: key,

          attendance_id: null,
          adjustment_id: null,

          time_in: "",
          time_out: "",

          original_time_in: "",
          original_time_out: "",

          adjusted_time_in: null,
          adjusted_time_out: null,

          late: 0,
          undertime: 0,
          overtime: 0,

          logs: logsMap[key],   // ✅ SHOW REAL LOGS

          notes: [],
        });

        d.add(1, "day");
      }

      return res.json({
        attendance_id: null,
        employee_id: employeeId,
        date_from: startYMD,
        date_to: endYMD,
        logs: results,
      });
    }

    // ==========================================
    // BUILD ATTENDANCE MAP
    // ==========================================
    const dayMap = {};

    for (const d of attendance.days || []) {
      const key = moment(d.work_day).format("YYYY-MM-DD");

      dayMap[key] = d;
    }

    // ==========================================
    // FINAL RESULT BUILD
    // ==========================================
    const results = [];

    let day = monthStart.clone();

    while (day.isSameOrBefore(monthEnd, "day")) {
      const formatted = day.format("YYYY-MM-DD");

      const dtr = dayMap[formatted];

      const originalTimeIn = formatTime(dtr?.time_in);
      const originalTimeOut = formatTime(dtr?.time_out);

      results.push({
        date: formatted,

        attendance_id: dtr?.id || null,
        adjustment_id: null,

        time_in: originalTimeIn,
        time_out: originalTimeOut,

        original_time_in: originalTimeIn,
        original_time_out: originalTimeOut,

        adjusted_time_in: null,
        adjusted_time_out: null,

        late: 0,
        undertime: 0,
        overtime: 0,

        logs: logsMap[formatted],  // ✅ ALWAYS SHOW LOGS

        notes: [],
      });

      day.add(1, "day");
    }

    return res.json({
      attendance_id: attendance.id,
      employee_id: employeeId,
      date_from: attendance.date_from,
      date_to: attendance.date_to,
      logs: results,
    });

  } catch (error) {
    console.error(error);

    return res.status(500).json({
      error: error.message,
    });
  }
};


