exports.Create = async (req, res) => {

    const {
        date,
        timeStart,
        timeEnd,
        description,
        employees
    } = req.body;

    const t = await sequelize.transaction();

    try {
// ---- validate employees ----
    if (!Array.isArray(employees) || employees.length === 0) {
      await t.rollback();
      return res.status(400).json({ message: 'Please select at least one employee.' });
    }

    // normalize to unique numeric ids
    const employeeIds = [...new Set(
      employees
        .map(e => Number(e))
        .filter(n => Number.isInteger(n) && n > 0)
    )];

    if (employeeIds.length === 0) {
      await t.rollback();
      return res.status(400).json({ message: 'Invalid employees payload.' });
    }

    // ---- create overtime header ----
    const overtime = await db.Overtime.create({
      date,
      time_start: timeStart,
      time_end: timeEnd,
      description
    }, { transaction: t });

    // ---- create employee applications (bulk) ----
    await db.EmployeeOvertimeApplication.bulkCreate(
      employeeIds.map(empId => ({
        overtime_id: overtime.id,
        employee_id: empId,
        status: 'Pending' // optional if you have default
      })),
      { transaction: t }
    );

    // ---- approvals ----
    const signatories = await db.ApprovalSetting.findAll({
      where: {
        // owner_id: req.user.id,
        type: 'Overtime',
        is_active: true
      },
      order: [['order', 'ASC']],
      transaction: t
    });

    await db.Approval.bulkCreate(
      signatories.map(sig => {
        return {
          setting_id: sig.id,
          document_id: overtime.id,
          status: 'Pending',
          signed_at: null,
          remarks: null,
          is_active: true
        };
      }),
      { transaction: t }
    );

    await t.commit();

    return res.status(201).json({
      message: 'Record Saved!'
    });

  } catch (error) {
    await t.rollback();
    console.error(error);
    return res.status(500).json({
      message: 'Failed to save overtime record',
      error: error.message
    });
  }

};

exports.Update = async (req, res) => {
    const { id } = req.params;

    const {
        date,
        timeStart,
        timeEnd,
        description,
        employees
    } = req.body;

    try {
        const empList = Array.isArray(employees) ? employees : [];

        // Update overtime header
        await Overtime.update({
            date,
            time_start: timeStart,
            time_end: timeEnd,
            description
        }, {
            where: { id }
        });

        // Get existing applications for this overtime
        const existingRecords = await EmployeeOvertimeApplication.findAll({
            where: {
                overtime_id: id
            }
        });

        const existingIds = existingRecords.map(e => e.id);
        const sentIds = empList.filter(e => e.id).map(e => e.id);

        for (const emp of empList) {
            if (emp.id && existingIds.includes(emp.id)) {
                // UPDATE existing
                await EmployeeOvertimeApplication.update({
                    employee_id: emp.employeeid,
                    status: emp.status
                }, {
                    where: { id: emp.id }
                });
            } else {
                // INSERT new
                await EmployeeOvertimeApplication.create({
                    overtime_id: id,
                    employee_id: emp.employeeid,
                    status: 'Pending'
                });
            }
        }

        // Deactivate removed employees
        const toDeactivate = existingIds.filter(oldId => !sentIds.includes(oldId));
        if (toDeactivate.length > 0) {
            await EmployeeOvertimeApplication.update({
                status: 'Cancelled'
            }, {
                where: {
                    id: toDeactivate
                }
            });
        }

        res.status(200).json({
            message: 'Record Updated!'
        });

    } catch (error) {
        console.error(error);
        res.status(500).json({
            message: 'Failed to update overtime record',
            error
        });
    }
};


