        const computeHours = (start, end) => {
            const startTime = new Date(`1970-01-01T${start}`);
            const endTime = new Date(`1970-01-01T${end}`);
            const diff = (endTime - startTime) / (1000 * 60 * 60);
            return diff > 0 ? diff : 0;
        };

