exports.Create = async (req, res) => {

    const { 
        code,
        name,
        starttime,
        endtime,
        breakminutes,
        graceminutes,
        earliestminutes,
        latestminutes,
        crossesmidnight,
        days
    } = req.body;

    const transaction = await sequelize.transaction();

    try {

        const exist = await db.Shift.findOne({
            where: { 
                code, name 
            }
        });

        if (exist) {
            return res.status(500).json({
                errors: [{
                    type: "field",
                    value: name,
                    msg: "Record already exists!",
                    path: "name",
                    location: "body",
                }],
            });
        }

        const shift = await db.Shift.create({
            code,
            name,
            start_time: starttime,
            end_time: endtime,
            break_minutes: breakminutes,
            grace_minutes: graceminutes,
            earliest_minutes: earliestminutes,
            latest_minutes: latestminutes,
            crosses_midnight: crossesmidnight
        }, { transaction });

        const sd = days.map(day => ({
            shift_id: shift.id,
            day_of_week: day
        }));
        await db.ShiftDay.bulkCreate(sd, { transaction });

        const s = await GetShift(shift.id);

        await transaction.commit();

        res.status(201).json({
            message: "Record Saved!", 
            shift: s
        });

    } catch (error) {

        await transaction.rollback();
        res.status(400).json({ 
            error: error.message 
        });

    }
};

exports.Update = async (req, res) => {

    const { 
        id 
    } = req.params

    const {
        code,
        name,
        starttime,
        endtime,
        breakminutes,
        graceminutes,
        earliestminutes,
        latestminutes,
        crossesmidnight,
        days
    } = req.body

    const transaction = await sequelize.transaction()

    try {
        // 1) check if record exists
        const shift = await db.Shift.findByPk(id, { transaction })
        if (!shift) {
            await transaction.rollback()
            return res.status(404).json({ message: 'Shift not found' })
        }

        // 2) check duplicates (exclude current id)
        const exist = await db.Shift.findOne({
            where: {
                [Op.or]: [{ code }, { name }],
                id: { [Op.ne]: id }
            },
            transaction
        })

        if (exist) {
            await transaction.rollback()
            return res.status(409).json({
                errors: [
                ...(exist.code === code
                    ? [{
                        type: "field",
                        value: code,
                        msg: "Code already exists!",
                        path: "code",
                        location: "body",
                    }]
                    : []),
                ...(exist.name === name
                    ? [{
                        type: "field",
                        value: name,
                        msg: "Name already exists!",
                        path: "name",
                        location: "body",
                    }]
                    : [])
                ]
            })
        }

        // 3) update shift
        await shift.update(
            {
                code,
                name,
                start_time: starttime,
                end_time: endtime,
                break_minutes: breakminutes,
                grace_minutes: graceminutes,
                earliest_minutes: earliestminutes,
                latest_minutes: latestminutes,
                crosses_midnight: crossesmidnight
            }, transaction
        )

        // 4) replace days (delete then insert)
        if (Array.isArray(days)) {
            await db.ShiftDay.destroy({
                where: { shift_id: id },
                transaction
            })

            const sd = days.map(day => ({
                shift_id: id,
                day_of_week: day
            }))

            if (sd.length) {
                await db.ShiftDay.bulkCreate(sd, { transaction })
            }
        }

        // 5) return updated shift with includes
        const s = await GetShift(id)

        await transaction.commit()

        return res.status(200).json({
            message: "Record Updated!",
            shift: s
        })

    } catch (error) {
        await transaction.rollback()
            return res.status(400).json({
            error: error.message
        })
    }
}


